using FixFinder.Core.LocalFixes;
using FixFinder.Core.Logic;

namespace FixFinder.Tests;

/// <summary>
/// A merge sort in each language that stops only when nothing is left - an empty list, a count of 0, or an empty range - so
/// with one item, or one place, left it calls itself with all of it again, with the change that stops at one as well; the
/// same sorts stopping at one, and programs near the mistake but not it, which are left alone. Each row is what the check gave
/// for the program when these were written.
/// </summary>
public class HalvingNeverStopsTests : IDisposable
{
    private readonly TempFolder _temp = new();

    public void Dispose()
    {
        _temp.Dispose();
        GC.SuppressFinalize(this);
    }

    private SourceFile Program(string fileName, string code)
    {
        var path = Path.Combine(_temp.Path, fileName);
        File.WriteAllText(path, code);
        return SourceFile.Read(path)!;
    }

    /// <summary>The file, the program, the check, the line it is said of, the line the change starts on, how many it takes away, and the lines it writes, one a line.</summary>
