    [Theory]
    [MemberData(nameof(Sorts))]
    public void AListSplitInHalfThatStopsOnlyWhenNothingIsLeftIsFound(string fileName, string code, string check, int line, int changeAt, int removed, string added)
    {
        var found = Assert.Single(LogicPatterns.All.Where(pattern => pattern.Id == check).SelectMany(pattern => pattern.Find(Program(fileName, code))));

        Assert.Equal(line, found.Line);
        Assert.Equal(changeAt, found.Fix!.StartLine);
        Assert.Equal(removed, found.Fix.RemoveCount);
        Assert.Equal(added.Split('\n'), found.Fix.NewLines);
    }

    /// <summary>
    /// The sorts stopping at one item, or one place; a tree built from a sorted list, whose halves leave out the middle; a sum
    /// and a largest worked out by halves, stopping at one; a binary search over lo up to hi that stops at one place; a sort
    /// with a stop for none and another for one; and one whose calls are inside a test for two items or more.
    /// </summary>
    [Theory]
    [InlineData("CopySort.java", "import java.util.Arrays;\n\npublic class CopySort {\n    static int[] merge(int[] left, int[] right) {\n        int[] merged = new int[left.length + right.length];\n        int i = 0;\n        int j = 0;\n        int k = 0;\n        while (i < left.length && j < right.length) {\n            if (left[i] <= right[j]) {\n                merged[k++] = left[i++];\n            } else {\n                merged[k++] = right[j++];\n            }\n        }\n        while (i < left.length) merged[k++] = left[i++];\n        while (j < right.length) merged[k++] = right[j++];\n        return merged;\n    }\n\n    static int[] mergeSort(int[] items) {\n        if (items.length <= 1) {\n            return items;\n        }\n        int mid = items.length / 2;\n        int[] left = mergeSort(Arrays.copyOfRange(items, 0, mid));\n        int[] right = mergeSort(Arrays.copyOfRange(items, mid, items.length));\n        return merge(left, right);\n    }\n\n    public static void main(String[] args) {\n        int[] numbers = mergeSort(new int[] {5, 2, 4, 1, 3});\n        StringBuilder line = new StringBuilder();\n        for (int number : numbers) {\n            if (line.length() > 0) line.append(' ');\n            line.append(number);\n        }\n        System.out.println(line);\n    }\n}\n")]
