    [InlineData("MergeSort.java", "import java.util.ArrayList;\nimport java.util.Arrays;\n\npublic class MergeSort {\n    static ArrayList<Integer> merge(ArrayList<Integer> left, ArrayList<Integer> right) {\n        ArrayList<Integer> merged = new ArrayList<>();\n        int i = 0;\n        int j = 0;\n        while (i < left.size() && j < right.size()) {\n            if (left.get(i) <= right.get(j)) {\n                merged.add(left.get(i++));\n            } else {\n                merged.add(right.get(j++));\n            }\n        }\n        merged.addAll(left.subList(i, left.size()));\n        merged.addAll(right.subList(j, right.size()));\n        return merged;\n    }\n\n    static ArrayList<Integer> mergeSort(ArrayList<Integer> items) {\n        if (items.size() <= 1) {\n            return items;\n        }\n        int middle = items.size() / 2;\n        ArrayList<Integer> left = new ArrayList<>();\n        left.addAll(items.subList(0, middle));\n        ArrayList<Integer> right = new ArrayList<>();\n        right.addAll(items.subList(middle, items.size()));\n        return merge(mergeSort(left), mergeSort(right));\n    }\n\n    public static void main(String[] args) {\n        ArrayList<Integer> numbers = mergeSort(new ArrayList<>(Arrays.asList(5, 2, 4, 1, 3)));\n        StringBuilder line = new StringBuilder();\n        for (int number : numbers) {\n            if (line.length() > 0) line.append(' ');\n            line.append(number);\n        }\n        System.out.println(line);\n    }\n}\n")]
