    [InlineData("sort.f90", "program sort_numbers\n  implicit none\n  integer :: numbers(5) = [5, 2, 4, 1, 3]\n  call sort_range(numbers, 1, 5)\n  print '(I0, 4(1X, I0))', numbers\ncontains\n  recursive subroutine sort_range(items, lo, hi)\n    integer, intent(inout) :: items(:)\n    integer, intent(in) :: lo, hi\n    integer :: mid\n    if (lo >= hi) return\n    mid = (lo + hi) / 2\n    call sort_range(items, lo, mid)\n    call sort_range(items, mid + 1, hi)\n    call merge(items, lo, mid, hi)\n  end subroutine sort_range\n\n  subroutine merge(items, lo, mid, hi)\n    integer, intent(inout) :: items(:)\n    integer, intent(in) :: lo, mid, hi\n    integer :: merged(hi - lo + 1)\n    integer :: i, j, k\n    i = lo\n    j = mid + 1\n    k = 1\n    do while (i <= mid .and. j <= hi)\n      if (items(i) <= items(j)) then\n        merged(k) = items(i)\n        i = i + 1\n      else\n        merged(k) = items(j)\n        j = j + 1\n      end if\n      k = k + 1\n    end do\n    do while (i <= mid)\n      merged(k) = items(i)\n      i = i + 1\n      k = k + 1\n    end do\n    do while (j <= hi)\n      merged(k) = items(j)\n      j = j + 1\n      k = k + 1\n    end do\n    items(lo:hi) = merged\n  end subroutine merge\nend program sort_numbers\n")]
