    [InlineData("sort.rs", "fn merge(left: Vec<i32>, right: Vec<i32>) -> Vec<i32> {\n    let mut merged = Vec::new();\n    let (mut i, mut j) = (0, 0);\n    while i < left.len() && j < right.len() {\n        if left[i] <= right[j] {\n            merged.push(left[i]);\n            i += 1;\n        } else {\n            merged.push(right[j]);\n            j += 1;\n        }\n    }\n    merged.extend_from_slice(&left[i..]);\n    merged.extend_from_slice(&right[j..]);\n    merged\n}\n\nfn merge_sort(items: Vec<i32>) -> Vec<i32> {\n    if items.len() <= 1 {\n        return items;\n    }\n    let mid = items.len() / 2;\n    let left = merge_sort(items[..mid].to_vec());\n    let right = merge_sort(items[mid..].to_vec());\n    merge(left, right)\n}\n\nfn main() {\n    let words: Vec<String> = merge_sort(vec![5, 2, 4, 1, 3]).iter().map(|number| number.to_string()).collect();\n    println!(\"{}\", words.join(\" \"));\n}\n")]
    [InlineData("Sort.scala", "object Sort {\n  def merge(left: List[Int], right: List[Int]): List[Int] = (left, right) match {\n    case (Nil, _) => right\n    case (_, Nil) => left\n    case (l :: ls, r :: rs) => if (l <= r) l :: merge(ls, right) else r :: merge(left, rs)\n  }\n\n  def mergeSort(items: List[Int]): List[Int] = {\n    if (items.length <= 1) items\n    else {\n      val (left, right) = items.splitAt(items.length / 2)\n      merge(mergeSort(left), mergeSort(right))\n    }\n  }\n\n  def main(args: Array[String]): Unit = println(mergeSort(List(5, 2, 4, 1, 3)).mkString(\" \"))\n}\n")]
