    [InlineData("SortRange.java", "public class SortRange {\n    static void merge(int[] items, int lo, int mid, int hi) {\n        int[] merged = new int[hi - lo + 1];\n        int i = lo;\n        int j = mid + 1;\n        int k = 0;\n        while (i <= mid && j <= hi) {\n            if (items[i] <= items[j]) {\n                merged[k++] = items[i++];\n            } else {\n                merged[k++] = items[j++];\n            }\n        }\n        while (i <= mid) merged[k++] = items[i++];\n        while (j <= hi) merged[k++] = items[j++];\n        System.arraycopy(merged, 0, items, lo, merged.length);\n    }\n\n    static void sortRange(int[] items, int lo, int hi) {\n        if (lo >= hi) return;\n        int mid = (lo + hi) / 2;\n        sortRange(items, lo, mid);\n        sortRange(items, mid + 1, hi);\n        merge(items, lo, mid, hi);\n    }\n\n    public static void main(String[] args) {\n        int[] numbers = {5, 2, 4, 1, 3};\n        sortRange(numbers, 0, numbers.length - 1);\n        StringBuilder line = new StringBuilder();\n        for (int number : numbers) {\n            if (line.length() > 0) line.append(' ');\n            line.append(number);\n        }\n        System.out.println(line);\n    }\n}\n")]
