    public void ASplitThatStopsAtOneIsLeftAlone(string fileName, string code)
    {
        var file = Program(fileName, code);
        Assert.Empty(LogicPatterns.All.Where(pattern => pattern.Id.EndsWith("halving-never-stops", StringComparison.Ordinal)).SelectMany(pattern => pattern.Find(file)));
    }
}
